let __v_234 = pyrt::literals::decode("{\"$tuple\":[\"Not too late at all. Being a beginner again is awkward rather than impossible, and the first few weeks are the awkward bit for everybody in the room, not just you.\",\"It isn't. What decides these things is a regular slot in the week rather than the year you start in - so put one in the diary and age stops being the question.\",\"No. Plenty of people take this sort of thing up later than they meant to, and they are usually the ones who keep turning up, because they are not in a hurry to look good.\",\"Not at all - if anything, waiting makes you better at it: you have already stopped caring what the room thinks, which is the hard part for most beginners.\"]}")?;
