let __v_1029 = pyrt::literals::decode("{\"$tuple\":[\"Rule of thumb: fix it while the part is a few pounds and you can fit it yourself. Replace it once the repair costs more than about half of a new one, or when it is already on its second fault — twice is usually the point where the money stops going in the right place.\",\"The usual test is cost against new: a cheap part you can fit yourself is worth doing, over about half the price of a new one is not, and the second fault on the same thing is the moment to stop. How old is it, and what would a new one cost you?\",\"Fix it if it is a part and a few pounds; bin it if the repair is half the price of new, or if this is the second thing to go wrong with it. If neither of those settles it, tell me the age and the quote and we can do the sums properly.\"]}")?;
