let __v_1030 = pyrt::literals::decode("{\"$tuple\":[\"That one is for whoever repairs them: whether it can be mended comes down to the part, and a shop will say in a minute with it in front of them - a quote is usually free. What is it, and what has it started doing?\",\"Ask a repair shop before you buy new. They can tell you whether the part is still made and what the job costs, and that settles it either way. What have you got, and what has gone wrong with it?\",\"Whether it can be fixed depends on the thing, so take it to someone who mends them and ask for a quote - free at most places, and it answers both halves of that. What is it?\"]}")?;
