let __v_1031 = pyrt::literals::decode("{\"$dict\":[[\"identity\",{\"$tuple\":[\"I'm a chatbot, not a person: a program built to help with everyday questions and have a chat. What can I do for you?\",\"I'm a chatbot — here to help and chat. Ask me anything, or just talk.\"]}],[\"memory\",{\"$tuple\":[\"I remember what we've said in this chat, but nothing from before it — so not yesterday, sorry. What was it about?\",\"Only this conversation: I keep what you tell me here, like your name and plans, but nothing carries over to a new chat. What were we talking about?\",\"What we say in this chat stays here for as long as we are talking, so ask me again later in it and I still have it. A new conversation starts empty, every time.\"]}],[\"privacy\",{\"$tuple\":[\"Nothing you type is written down or sent anywhere - what you tell me is used here, in this conversation, and nowhere else. No account, no log, and nobody else reading it.\",\"Private to this chat. I keep no file of it and I pass nothing on; what you say stays here while we talk, so I can follow it, and that is all.\",\"Nothing leaves this conversation: no database, no record, nobody else seeing it. I hold what you say only for as long as we are talking.\"]}],[\"trust\",{\"$tuple\":[\"Hold me to being honest: when I don't know, I say so instead of guessing. Treat the everyday things as a knowledgeable friend's advice, and check anything that matters.\",\"I'd rather tell you I don't know than make something up, so trust me on the ordinary stuff and get a second word on the rest.\",\"I don't invent answers. If something is beyond me I'll say it plainly, and anything that matters is worth checking with someone who would know.\"]}],[\"secret\",{\"$tuple\":[\"Yes - nothing you type is written down or sent anywhere, so it stays between us. What is it? The one thing I can't do is act on it: if somebody needs help in the real world, tell a person who can give it.\",\"Kept: no record, no log, nothing passed on. Go on. Anything that needs doing rather than saying, though, take to someone with hands - me knowing about it is not the same as it being dealt with.\",\"Nothing you tell me leaves this chat, so a secret is safe here. What's on your mind? If it is the kind of thing somebody should know about, I'd rather you told them as well.\"]}],[\"judging\",{\"$tuple\":[\"Not judging, no. Say it plainly and we'll look at it together.\",\"No judgement here - whatever it is, half of it usually makes sense once it is said out loud. Tell me what happened.\",\"Nothing you tell me gets graded. Tell me what's going on and we'll take it from there.\"]}],[\"help\",{\"$tuple\":[\"Everyday things: cooking, travel, money, tech, health questions, plans, and a chat when you want one. What's on your mind?\",\"Cooking, travel, money, work, gadgets, kids, feelings — everyday questions and plans. Ask away.\"]}],[\"trust\",{\"$tuple\":[\"Trust me the way you would a well-read friend: good on the everyday, worth a check on the things that cost money or matter to your health. I say so when I am unsure, and anything I give you a number for is worth a second look. Which is it?\",\"You can, with a limit: I am a program working from what is written into me, not someone who checked today's prices or read your test results. Everyday questions, yes; a dose, a deadline or a legal thing, check it. What are you weighing up?\"]}]]}")?;
frame.store("ABOUT", __v_1031.clone())?;
let __v_1032 = pyrt::literals::decode("{\"$tuple\":[\"Not in numbers, no — I don't keep a tally. What I do have is everything you've said in this chat. What were you after?\",\"No count, I'm afraid: nothing runs from one chat to the next, so all I have is this conversation. What can I help with?\"]}")?;
