let __v_1945 = pyrt::literals::decode("{\"$tuple\":[\"Ask once more, and ask what would make it a yes. A no with a reason is something you can plan around; one without leaves you guessing.\",\"Worth one more go, put as a question: what would have to change? If it is still no, at least you know where you stand.\",\"Then ask why not, and what would move it. What they say is worth more than the no itself.\",\"Ask once more with one change in it: name the smallest version they could say yes to, and ask what would make the bigger one possible.\",\"Put it to them once more in your own words and ask what would change their mind. Either answer helps you decide what to do next.\"]}")?;
