let __v_1947 = pyrt::literals::decode("{\"$tuple\":[\"Take them with you and let the optician or the audiologist make the case - the number on the test is the argument, and it is not yours to make. Frames in a style they like, or an aid that sits behind the ear instead of in it, is usually what settles it.\",\"Then ask what they would wear or use, rather than what they should: the small ones, the ones that look like ordinary glasses, the ones that only come out for the television. Book the test so the answer comes from the person doing it, and go along to the appointment.\"]}")?;
