let __v_1948 = pyrt::literals::decode("{\"$tuple\":[\"Ring the surgery yourself and describe what you have seen, then ask what they suggest - a GP can usually find a reason to call them in that a son or daughter cannot. Offer to book it and go with them; being driven and having somebody in the waiting room makes a difference.\",\"Then do not argue the appointment, argue the one thing that has changed and when it started. If the trip out is the problem, ask for a phone call instead of a visit, and let the GP ask them to come in. A no to the surgery is often a no to the journey.\",\"Say what you have noticed and leave the diagnosis to the doctor - what they will not hear from you is what is wrong with them. A district nurse, a pharmacist or a friend of their own age can often get them there when a relative cannot.\"]}")?;
