let __v_1949 = pyrt::literals::decode("{\"$tuple\":[\"Ask what they would take instead of what they will not: one morning a week, somebody to do the garden, you doing the shopping. The council's care needs assessment is free and it is the door to all of it, and it arrives as them asking rather than you arranging.\",\"Start with the job they hate rather than the word carer - nobody wants to be looked after, and plenty of people will take help with the bins, the windows and the bedding. Their GP or Age UK will suggest it as well, which lands better than it coming from family.\",\"Then find out what the no is really to: a stranger in the house, being watched, or paying for something they think they can still do. Fix that one and the help becomes a smaller yes - and say what you will not be able to keep doing, plainly, so it is not a surprise later.\"]}")?;
