let __v_2260 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"cats or dogs\",\"cat or dog\",\"dogs or cats\",\"dog or cat\"]},{\"$tuple\":[\"Dogs by a whisker: company on a walk beats almost anything. Cats are the easier flatmate.\",\"Dogs for me, though I would not turn down a cat that ignored me politely.\"]}]},{\"$tuple\":[{\"$tuple\":[\"tea or coffee\",\"coffee or tea\"]},{\"$tuple\":[\"Coffee in the morning, tea after four: two different jobs.\",\"Tea, if I had to choose one. Coffee is a tool, tea is a pause.\"]}]},{\"$tuple\":[{\"$tuple\":[\"best season\",\"favourite season\",\"favorite season\",\"best time of year\"]},{\"$tuple\":[\"Early autumn: warm enough to sit outside, dark early enough to stay in, and no pressure to be doing something.\",\"Late spring. Everything is green and nobody has started complaining about the heat yet.\"]}]},{\"$tuple\":[{\"$tuple\":[\"morning or evening\",\"morning or the evening\",\"evenings or mornings\"]},{\"$tuple\":[\"Morning, by a mile. The day is still yours then.\"]}]},{\"$tuple\":[{\"$tuple\":[\"recline\"]},{\"$tuple\":[\"Recline it, but only on a long flight, and check behind you first. A short daytime hop, no.\"]}]},{\"$tuple\":[{\"$tuple\":[\"pineapple\"]},{\"$tuple\":[\"On pizza, yes. Fruit and cheese is not the crime people make it out to be.\"]}]},{\"$tuple\":[{\"$tuple\":[\"toilet roll\",\"toilet paper\"]},{\"$tuple\":[\"Over. It hangs better and you can see how much is left.\"]}]},{\"$tuple\":[{\"$tuple\":[\"book or film\",\"film or book\",\"book or the film\"]},{\"$tuple\":[\"The book first, always; then the film can only be a bonus.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite book\",\"favorite book\",\"best book\"]},{\"$tuple\":[\"A collected volume of a newspaper column I read in the bath: short pieces are easy to start and easy to put down.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite film\",\"favorite film\",\"best film\",\"favourite movie\",\"favorite movie\"]},{\"$tuple\":[\"Anything where people mostly talk in kitchens. A plot is optional; good company is not.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite food\",\"favorite food\",\"best food\"]},{\"$tuple\":[\"Roast potatoes, and I am not going to pretend otherwise.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite thing to cook\",\"favorite thing to cook\",\"favourite thing to make\",\"favorite thing to make\",\"favourite recipe\",\"favorite recipe\",\"best thing to cook\",\"favourite thing to eat\",\"favorite thing to eat\"]},{\"$tuple\":[\"One pan and no recipe: a traybake, a frittata, whatever is in the fridge going soft. Less washing up, more eating.\",\"Sausages in a tin with onions and apples, on a cold day. Nothing clever, and it works every time.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite thing to read\",\"favorite thing to read\",\"favourite author\",\"favorite author\",\"favourite writer\",\"favorite writer\"]},{\"$tuple\":[\"Short things I can pick up and put down: a newspaper column, an essay, a book of letters.\",\"Old advice books - cookery, gardening, how to fix a bike. They assume nothing and they are usually right.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite colour\",\"favorite color\",\"favourite color\",\"favorite colour\"]},{\"$tuple\":[\"Green, the sort that looks grey in a cold light.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite city\",\"favorite city\",\"best city\"]},{\"$tuple\":[\"Whichever one I can walk across in an afternoon.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite animal\",\"favorite animal\",\"best animal\"]},{\"$tuple\":[\"Herons. They stand in the rain looking unbothered, which I admire.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite show\",\"favorite show\",\"favourite series\",\"favorite series\",\"favourite tv show\",\"favorite tv show\",\"favourite tv programme\",\"favorite tv program\",\"favourite programme\",\"favorite program\",\"favourite thing to watch\",\"favorite thing to watch\",\"watch much tv\",\"watch a lot of tv\",\"watch much television\"]},{\"$tuple\":[\"Something slow and British where not much happens for a while, and then everything does: *Detectorists* for the first, *Happy Valley* for the second.\",\"The same few comedies on repeat. *Peep Show* is still the one I would put on now.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite actor\",\"favorite actor\",\"favourite actress\",\"favorite actress\"]},{\"$tuple\":[\"Olivia Colman. She does more with one look than most people manage with a speech.\",\"Anyone who can say a whole paragraph with their face. Olivia Colman, if you make me pick.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite song\",\"favorite song\",\"favourite album\",\"favorite album\",\"favourite band\",\"favorite band\",\"favourite music\",\"favorite music\",\"favourite singer\",\"favorite singer\",\"what music do you like\"]},{\"$tuple\":[\"*Rumours*, still. It is the one album where every song is the good one.\",\"Anything with a bit of swing to it. Loud is fine, clever is optional.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite drink\",\"favorite drink\"]},{\"$tuple\":[\"Tea, and I would rather not count how many. Coffee is a tool, tea is a pause.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite day\",\"favorite day\",\"best day of the week\"]},{\"$tuple\":[\"Saturday morning, before anyone needs anything. The whole weekend is still ahead.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite time of day\",\"favorite time of day\",\"best time of day\"]},{\"$tuple\":[\"Early morning, just after the kettle. Nobody wants anything from me yet.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite biscuit\",\"favorite biscuit\",\"favourite cookie\",\"favorite cookie\"]},{\"$tuple\":[\"A digestive, and I will not be talked out of it.\",\"Shortbread. Plain, buttery, gone in two bites.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite thing to talk about\",\"favorite thing to talk about\",\"favourite thing to chat about\",\"favorite thing to chat about\"]},{\"$tuple\":[\"Whatever the person has just brought me. The best part of a conversation is finding out what somebody actually cares about.\",\"Small practical problems. There is nearly always something useful to say about a kettle that will not boil.\"]}]},{\"$tuple\":[{\"$tuple\":[\"favourite thing about your job\",\"favorite thing about your job\",\"like about your job\",\"like about the job\",\"like most about your job\",\"best thing about your job\",\"best thing about the job\",\"best bit about your job\",\"best bit of your job\",\"good thing about your job\",\"love about your job\",\"do you like your job\",\"do you like what you do\",\"do you enjoy your job\"]},{\"$tuple\":[\"The moment a question turns out to have a good answer after all. That is most of the job.\",\"People telling me things they have not said to anyone else yet. I try to be worth it.\"]}]}]}")?;
