let __v_4024 = pyrt::literals::decode("{\"$tuple\":[\"Wrap up and get a hot drink in you - is the heating on where you are?\",\"Hot water bottle and something warm inside you. That beats waiting for the heating.\",\"Cold gets into everything. Is there a radiator you can sit next to?\",\"Another layer and something hot to drink. Is it the whole place, or just the room you are in?\",\"That is too cold to think straight in. Get the heating on and a jumper on top of that.\"]}")?;
