let __v_4026 = pyrt::literals::decode("{\"$tuple\":[\"Then go and eat something - what have you got in?\",\"That is your body asking. Something with protein in it holds you longer than a biscuit.\",\"Eat first and sort the rest out after. What is quickest to hand?\",\"You are running on empty there. Toast and an egg beats waiting for a proper meal.\",\"Go and get something now, even if it is small - a sandwich is enough to steady you.\"]}")?;
frame.store("BODY_HUNGRY", __v_4026.clone())?;
let __v_4027 = pyrt::literals::decode("{\"$tuple\":[\"Get a glass of water in you now - are you at home, or out?\",\"Thirsty means you are already behind. A full glass of water, not a sip.\",\"Water first, then whatever you were doing. Is there a tap handy?\",\"Have a proper drink of water and keep the glass next to you afterwards.\"]}")?;
