let __v_4028 = pyrt::literals::decode("{\"$tuple\":[\"Sit down before anything else - did it come on when you stood up?\",\"Get sat down and have some water. Does it settle if you stay still for a minute?\",\"Take that slowly and hold on to something. Has it been creeping up on you, or was it sudden?\",\"Sit down and put your head down for a minute. If it keeps happening it is worth getting looked at.\",\"Have you eaten anything today? Low blood sugar does that - get something in you and sit down.\"]}")?;
frame.store("BODY_LIGHT_HEAD", __v_4028.clone())?;
let __v_4029 = pyrt::literals::decode("{\"$tuple\":[\"Sit up rather than lie flat and sip water - is anything staying down?\",\"Plain and dry beats anything rich right now: toast, a bit of rice. When did it start?\",\"Go steady with small sips. Is it just queasy, or have you been sick?\",\"Fresh air and water, and nothing heavy for an hour or two. Does it come in waves?\",\"That is a rotten way to spend an evening. Is it something you ate, do you think?\"]}")?;
frame.store("BODY_QUEASY", __v_4029.clone())?;
let __v_4030 = pyrt::literals::decode("{\"$tuple\":[\"Something hot to drink and ten minutes of steam in the bathroom - is it a cold coming on?\",\"That is usually the cold starting in the nose and throat. Is it blocked, or running?\",\"Honey in hot water and rest your voice - how long has it been like that?\",\"Keep the fluids up and get an early night. Is it the nose, the throat, or both?\",\"A cold runs its week and there is no rushing it. Are you blocked up, or is it sore?\"]}")?;
