let __v_4588 = pyrt::literals::decode("{\"$dict\":[[\"cold\",{\"$tuple\":[\"Bit parky, isn't it. Extra layer on, and put the heating on an hour before you want it warm rather than when you're cold.\",\"Cold one. Thick socks make more difference than people expect.\",\"That sort of cold gets into the bones. Hot drink, something warm on, and don't sit still in one room too long.\",\"Freezing out, isn't it. Shut the curtains at dusk and it holds the heat in.\"]}],[\"rain\",{\"$tuple\":[\"Raining again. Good day for the kettle and something slow on the telly.\",\"That sort of rain gets in everywhere. Coat rather than umbrella today, and leave the washing till tomorrow.\",\"Wet one, then. Shoes stuffed with newspaper overnight dry out properly, if you get caught in it.\",\"Never mind. It's a good excuse to do nothing much indoors.\"]}],[\"wind\",{\"$tuple\":[\"Blowy out there. Anything light in the garden will be next door by teatime.\",\"Wind like that takes doors with it. Worth propping the gate before it does.\",\"That's a bin-day wind. Hold on to the wheel if you're driving in it.\",\"Nasty wind, that. Good reason to stay in.\"]}],[\"hot\",{\"$tuple\":[\"Hot one, isn't it. Curtains shut while the sun's on the windows really does keep it cooler in.\",\"Too hot to do anything fast. Cold drink, water on the wrists, and save the jobs for this evening.\",\"That kind of heat takes it out of you. Drink more than you think you need.\",\"Boiling, isn't it. A bowl of ice in front of a fan does more than the fan on its own.\"]}],[\"grey\",{\"$tuple\":[\"Grey one. Put the lamp on early rather than at dusk and the afternoon feels less long.\",\"Grim out, isn't it. Nothing wrong with a quiet one indoors.\",\"Miserable out. Good day for the job you've been putting off, or for none at all.\",\"Dull one. It's the light more than the cold that gets people.\"]}],[\"fog\",{\"$tuple\":[\"Foggy one. Lights on even in the day, and more room than you think you need.\",\"Thick out there. Worth leaving a bit earlier while it's like this.\",\"Fog like that slows everything down. Nothing wrong with a slow start.\"]}],[\"sun\",{\"$tuple\":[\"Lovely, isn't it. Get out in it for a bit, even if it's only round the block.\",\"Beautiful out. Worth taking your cup of tea outside.\",\"That's the day for being outdoors. Suncream on if you're out past eleven.\",\"Gorgeous. That sort of day makes everything easier.\"]}],[\"mild\",{\"$tuple\":[\"No complaints then. Those are the days to be out in without thinking about it.\",\"Mild one, that. Good day for the jobs you keep putting off, or for none at all.\",\"Fair enough. The days that ask nothing of you are the ones worth using.\",\"Not bad at all, then. Worth a walk while it is like this.\"]}]]}")?;
