let __v_4589 = pyrt::literals::decode("{\"$dict\":[[\"cold\",{\"$tuple\":[\"Cold one coming. Anything outside that hates frost is worth bringing in tonight.\",\"Meant to turn cold. Get the grit out and the car warmed before you need either.\",\"Cold forecast. Layers for the morning, and leave the heating on a timer.\"]}],[\"rain\",{\"$tuple\":[\"Rain coming. Anything you want dry is worth doing before it arrives.\",\"Wet forecast. Coat rather than umbrella tomorrow, because the wind comes with it.\",\"Rain later, then. Put the outside bit of the day in the morning if you can.\"]}],[\"wind\",{\"$tuple\":[\"Wind coming. Anything light in the garden will be next door by tomorrow night.\",\"Blowy forecast. Worth checking the gate and the bins before it gets going.\",\"Wind later, then. Anything loose up high is worth sorting while it is calm.\"]}],[\"mild\",{\"$tuple\":[\"Mild forecast. Nothing to plan around, which is the best kind of day.\",\"Nothing much coming, weather-wise. Good day to have something booked.\",\"Fair forecast. Worth putting the outside thing in while it holds.\"]}],[\"hot\",{\"$tuple\":[\"Heat coming. Curtains shut in the morning really does keep it cooler in.\",\"Hot forecast. Jobs in the morning, and the afternoon for nothing much.\",\"Meant to be hot. Worth getting the fan down before you need it.\"]}],[\"grey\",{\"$tuple\":[\"Grey forecast. Nothing much to plan around, unless you were counting on the light.\",\"Meant to be dull. Fine day for the job you have been putting off indoors.\",\"Grey one coming. Put the lamp on early and the afternoon feels less long.\"]}],[\"fog\",{\"$tuple\":[\"Fog forecast. Lights on in the morning and more room than you would leave.\",\"Meant to be foggy. Worth setting off ten minutes earlier while it lifts.\",\"Fog coming. Anything you were going to drive for is easier after it clears.\"]}],[\"sun\",{\"$tuple\":[\"Nice one coming. Worth saving the outdoor bit of the day for it.\",\"Sun forecast. Suncream in the bag if you are out past eleven.\",\"Meant to be lovely. That is the day for the thing you keep putting off.\"]}]]}")?;
